import{_ as t,a as e}from"./chunks/station-form.bf54c130.js";import{_ as i,o,c as n,Q as s}from"./chunks/framework.b67c47e6.js";const b=JSON.parse('{"title":"Setting Up Production Lines","description":"","frontmatter":{},"headers":[],"relativePath":"tutorials/production_lines/index.md","filePath":"tutorials/production_lines/index.md","lastUpdated":1790346505000}'),a={name:"tutorials/production_lines/index.md"},r=s('<h1 id="setting-up-production-lines" tabindex="-1">Setting Up Production Lines <a class="header-anchor" href="#setting-up-production-lines" aria-label="Permalink to &quot;Setting Up Production Lines&quot;">​</a></h1><p>This tutorial walks you through configuring your production lines, stations, checklists, and machines from scratch.</p><nav class="table-of-contents"><ul><li><a href="#prerequisites">Prerequisites</a></li><li><a href="#step-1-create-a-production-line">Step 1: Create a Production Line</a></li><li><a href="#step-2-add-stations">Step 2: Add Stations</a></li><li><a href="#step-3-add-checklist-items">Step 3: Add Checklist Items</a></li><li><a href="#step-4-set-up-machines-optional">Step 4: Set Up Machines (Optional)</a></li><li><a href="#step-5-test-your-configuration">Step 5: Test Your Configuration</a></li><li><a href="#next-steps">Next Steps</a></li></ul></nav><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>You must have <strong>manager</strong> or <strong>admin</strong> access to your company.</li><li>At least one project should be set up to test the configuration.</li></ul><h2 id="step-1-create-a-production-line" tabindex="-1">Step 1: Create a Production Line <a class="header-anchor" href="#step-1-create-a-production-line" aria-label="Permalink to &quot;Step 1: Create a Production Line&quot;">​</a></h2><ol><li>In the left menu, in company-wide mode, open <strong>Production Settings &gt; Production lines</strong>.</li><li>Click the <strong>New Production Line</strong> tile at the top of the view.</li><li>Fill in the form: <ul><li><strong>Name</strong> — A descriptive name for the line (e.g., &quot;Wall Panel Line 1&quot;).</li><li><strong>Tipo</strong> — Select which constructible categories this line produces (assemblies, modules and/or parts).</li><li><strong>Client ID</strong> — Optional. Add one or more external identifiers if this line needs to be matched from an external system (e.g. ERP). You can add multiple IDs if the line is referenced by more than one system.</li></ul></li><li>Click <strong>Save</strong>.</li></ol><p><img src="'+t+'" alt="The production line form"></p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Every company needs at least one production line. You can create multiple lines for different product types or parallel manufacturing.</p></div><h2 id="step-2-add-stations" tabindex="-1">Step 2: Add Stations <a class="header-anchor" href="#step-2-add-stations" aria-label="Permalink to &quot;Step 2: Add Stations&quot;">​</a></h2><p>Stations represent the sequential steps in your production process.</p><ol><li>In the row of the production line you just created, click the <strong>New Production station</strong> tile. To reuse a station you already have, use <strong>Add existing station</strong> instead.</li><li>Configure the station: <ul><li><strong>Name</strong> — E.g., &quot;Framing&quot;, &quot;Cladding&quot;, &quot;Quality Check&quot;.</li><li><strong>Client ID</strong> — Optional external identifier if integrating with other systems.</li><li><strong>Zones</strong> — Which zones this station handles (e.g., zone 0 for a typical framing station).</li><li><strong>Machine station</strong> — If this is a machine station (e.g., Mobi One), tick it and pick the machine setup. You can also do this later, once the setup exists (see Step 4).</li></ul></li><li>Click <strong>Save</strong>, and repeat for each station in your production process.</li></ol><p><img src="'+e+'" alt="The station form"></p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Order your stations in the sequence they&#39;ll be performed: drag a station card by its handle to move it. Production workers will see checklists in this order in the <a href="/guide/viewer/">Viewer</a>.</p></div><h2 id="step-3-add-checklist-items" tabindex="-1">Step 3: Add Checklist Items <a class="header-anchor" href="#step-3-add-checklist-items" aria-label="Permalink to &quot;Step 3: Add Checklist Items&quot;">​</a></h2><p>Each station can have checklist tasks that production workers must complete.</p><ol><li>Open a station with its edit button and, in the <strong>Checklist</strong> block, click <strong>Add item</strong>.</li><li>Configure: <ul><li><strong>Task text</strong> — The instruction shown to the worker (e.g., &quot;Check frame alignment&quot;).</li><li><strong>DOCS</strong> — Optional documentation for the task (guidelines, specifications). Available once the station has been saved.</li><li><strong>Enable when</strong> — <em>Always</em>, or only when the design has one of the task&#39;s <strong>Branches</strong> or <strong>Zones</strong> (<em>If Branch in Design</em>, <em>If Zone in Design</em>, <em>If Branch in Zone of Design</em>).</li><li><strong>QC Inclusion Criteria</strong> — Choose how often this task appears: <ul><li><strong>All proofs</strong> — Every constructible gets this task.</li><li><strong>1/n</strong> — Added once every n constructibles (for periodic quality checks).</li><li><strong>1/n randomized</strong> — Same as 1/n but at random intervals.</li></ul></li><li><strong>Require form</strong>, <strong>QR field</strong>, <strong>Require picture</strong> — Optional. What the worker has to fill in, scan or photograph to complete the task.</li></ul></li><li>Repeat for all tasks at this station, then click <strong>Save</strong>.</li></ol><p>The task in the middle of the station form above is one checklist item: task text, zones, <em>Enable when</em>, <em>QC Inclusion Criteria</em> and, on the right, the docs and what the task requires.</p><h2 id="step-4-set-up-machines-optional" tabindex="-1">Step 4: Set Up Machines (Optional) <a class="header-anchor" href="#step-4-set-up-machines-optional" aria-label="Permalink to &quot;Step 4: Set Up Machines (Optional)&quot;">​</a></h2><p>If any station uses automated equipment (e.g., a Mobi One):</p><ol><li>Open <strong>Production Settings &gt; Machine Settings</strong>.</li><li>Click the <strong>New Machine setup</strong> tile, give it a name and pick the <strong>Model</strong>.</li><li>Configure the machine settings (see <a href="/guide/machine_files/machines/mobi_one/">Mobi One</a> for an example) and click <strong>Save</strong>.</li><li>Back in <strong>Production lines</strong>, edit the station, tick <strong>Machine station</strong> and pick the setup. For a line that is one machine, such as a saw line, tick <strong>Line machine</strong> in the line form instead.</li></ol><h2 id="step-5-test-your-configuration" tabindex="-1">Step 5: Test Your Configuration <a class="header-anchor" href="#step-5-test-your-configuration" aria-label="Permalink to &quot;Step 5: Test Your Configuration&quot;">​</a></h2><ol><li>Open a project that has designs and constructibles.</li><li>Start production on a constructible in the <a href="/guide/viewer/">Viewer</a>.</li><li>Verify that: <ul><li>The correct stations appear in order.</li><li>Checklist tasks are shown for each station.</li><li>Machine files can be generated (if applicable).</li></ul></li></ol><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><a href="/tutorials/projects/">Build a Project</a> — Upload files and generate designs.</li><li><a href="/tutorials/ifcps/">IFC Parsing Setup</a> — Configure how IFC files are interpreted.</li><li><a href="/guide/planning/">Production Planning</a> — Schedule constructibles on the calendar.</li></ul>',25),l=[r];function c(h,d,u,p,g,m){return o(),n("div",null,l)}const S=i(a,[["render",c]]);export{b as __pageData,S as default};
